import type { Localized } from "./i18n";
import data from "./data/notables.json";

// The people the people games are played with: Lifelines, Clue Ladder, Born
// Here and Could They Have Met? data/notables.json is generated by
// scripts/fetch-notables.mjs from Wikidata (CC0) — don't edit it by hand;
// change the roster in scripts/notables-roster.mjs and run it again.
// Who When Where's people are among them, under the same ids.

export type NotablePlace = {
  name: Localized;
  country: Localized | null;
  lat: number;
  lon: number;
};

export type Notable = {
  id: string;
  qid: string;
  name: Localized;
  /** A short description that names neither the person nor their dates. */
  description: Localized;
  /** Their main occupation: "physicist". */
  field: Localized;
  sex: "m" | "f" | null;
  /** Years are negative BC (historical numbering: there is no year 0). */
  born: { year: number; place: NotablePlace };
  died: { year: number; place: NotablePlace | null };
  citizenship: Localized | null;
  /** A notable work, when Wikidata names one. */
  work: Localized | null;
  wiki: { en: string; pt: string | null };
  /** How many Wikipedias have an article on them: a rough measure of fame. */
  fame: number;
  /** The name itself names a place, a people or a ruler tied to one (Joan of Arc, Julius Caesar). */
  placeInName?: boolean;
};

export const NOTABLES = data as Notable[];

const byId = new Map(NOTABLES.map((person) => [person.id, person]));

export const notableById = (id: string): Notable | undefined => byId.get(id);

/** How many years both were alive: 0 when their lives never overlapped. */
export function lifespanOverlap(a: Notable, b: Notable): number {
  return Math.max(0, Math.min(a.died.year, b.died.year) - Math.max(a.born.year, b.born.year));
}
